    public async Task<JsonElement> RunAsync(JsonElement input, CancellationToken cancellationToken = default)
    {
        Begin();
        try
        {
            if (state.Pending.Count != 0) throw new AgentSessionException("explicit reconciliation required; no call will be retried", inDoubt: true);
            if (state.Final) return state.FinalResult.Clone();
            return await ExecuteAsync(input, cancellationToken).ConfigureAwait(false);
