            catch (Exception error) { failure = new AgentSessionException("provider cleanup failed; callbacks remain caller-owned", failure is null ? error : new AggregateException(failure, error)); }
        }
        if (failure is not null)
        {
            if (state.Pending.Any(item => item.Mutation)) throw new AgentSessionException("explicit reconciliation required; no call will be retried", failure, true);
            System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(failure).Throw();
        }
        return final;
    }
}
